ALTER TABLE `company_config` ADD `positions` text;--> statement-breakpoint
ALTER TABLE `project_members` ADD `position_id` text;--> statement-breakpoint
-- Pronista §Position-based permission — seed 2 ตำแหน่งเริ่มต้น เทียบเท่า editor/viewer เดิม (lossless)
UPDATE company_config SET positions = '[{"id":"pos_full_access","name":"เข้าถึงเต็มรูปแบบ","sortOrder":0,"permissions":{"tabs":{"sprint":true,"docs":true,"assets":true,"backlogEpic":true,"backlogStory":true,"backlogTask":true,"backlogDefect":true,"backlogCr":true,"backlogSummary":true},"actions":{"task":{"create":true,"edit":true,"delete":true},"doc":{"create":true,"edit":true,"delete":true},"sprint":{"create":true,"edit":true,"delete":true},"defect":{"create":true,"edit":true,"delete":true},"cr":{"create":true,"edit":true,"delete":true}}}},{"id":"pos_view_only","name":"ดูอย่างเดียว","sortOrder":1,"permissions":{"tabs":{"sprint":true,"docs":true,"assets":true,"backlogEpic":true,"backlogStory":true,"backlogTask":true,"backlogDefect":true,"backlogCr":true,"backlogSummary":true},"actions":{"task":{"create":false,"edit":false,"delete":false},"doc":{"create":false,"edit":false,"delete":false},"sprint":{"create":false,"edit":false,"delete":false},"defect":{"create":false,"edit":false,"delete":false},"cr":{"create":false,"edit":false,"delete":false}}}}]' WHERE id = 1;--> statement-breakpoint
-- backfill: map old editor/viewer role -> positionId (role เดิมยังอยู่ครบ ไม่ลบ)
UPDATE project_members SET position_id = 'pos_full_access' WHERE role = 'editor';--> statement-breakpoint
UPDATE project_members SET position_id = 'pos_view_only' WHERE role = 'viewer';